triggers_atendimento_paciente.body:
  CREATE OR REPLACE EDITIONABLE TRIGGER "TASY"."INT_PFCS_ATENDIMENTO_PACIENTE" 
AFTER insert or update or delete ON ATENDIMENTO_PACIENTE
FOR EACH ROW

DECLARE
ds_clinica_w			valor_dominio.ds_valor_dominio%type;
ds_sintoma_paciente_w	queixa_paciente.ds_queixa%type;
cd_cgc_w				varchar2(35);
cd_escala_triagem_w		triagem_classif_risco.ie_emergency_severity_score%type;
ie_status_w				varchar2(15) := 'arrived';
ie_status_alta_w		varchar2(10) := null;
ds_status_alta_w		varchar2(5) := null;
nm_setor_leito_w 		varchar2(150);
ie_status_admissao_w	varchar2(10) := null;
ds_status_admissao_w	varchar2(10) := null;
nr_seq_interno_w		atend_paciente_unidade.nr_seq_interno%type;
dt_atualizacao_w		triagem_pronto_atend.dt_atualizacao%type; 
ie_status_request_w		varchar2(10) := 'inactive';
param_version_pfcs_w	funcao_param_usuario.vl_parametro%type;
ie_tipo_atendimento_w	atendimento_paciente.ie_tipo_atendimento%type := null;
DT_PREVISTO_ALTA_w		atendimento_paciente.DT_PREVISTO_ALTA%type := sysdate;
PRAGMA AUTONOMOUS_TRANSACTION;

BEGIN

obter_param_usuario(9041,14, obter_perfil_ativo, obter_usuario_ativo, nvl(wheb_usuario_pck.get_cd_estabelecimento, :new.cd_estabelecimento), param_version_pfcs_w);

if (wheb_usuario_pck.get_nm_usuario is not null and wheb_usuario_pck.get_ie_executar_trigger = 'S' and param_version_pfcs_w is not null) then

	if (inserting) or (updating and ((:old.ie_tipo_atendimento <> :new.ie_tipo_atendimento) or (:old.cd_procedencia <> :new.cd_procedencia) or (:old.cd_medico_resp <> :new.cd_medico_resp) or (:old.dt_cancelamento is null and :new.dt_cancelamento is not null)
		or (:old.dt_alta is null and :new.dt_alta is not null) or (:old.dt_alta is not null and :new.dt_alta is null) or (:old.dt_alta_medico is null and :new.dt_alta_medico is not null) or (:old.dt_alta_medico is not null and :new.dt_alta_medico is null) or (:new.nr_seq_triagem is not null and nvl(:old.nr_seq_triagem,-1) <> :new.nr_seq_triagem)
		or (:old.dt_inicio_observacao is null and :new.dt_inicio_observacao is not null) or (:old.dt_inicio_observacao is not null and :new.dt_inicio_observacao is null)
		or (:old.dt_fim_observacao is null and :new.dt_fim_observacao is not null) or (:old.dt_fim_observacao is not null and :new.dt_fim_observacao is null)
		or (:old.dt_previsto_alta is null and :new.dt_previsto_alta is not null) or (:old.dt_previsto_alta is not null and :new.dt_previsto_alta is null)
		or (coalesce(:old.ie_clinica,-1) <> coalesce(:new.ie_clinica,-1))
		or (:old.dt_previsto_alta <> :new.dt_previsto_alta)
		or (:old.dt_fim_triagem is null and :new.dt_fim_triagem is not null)
        or (:old.dt_fim_triagem is not null and :new.dt_fim_triagem is null) 
		or (:old.dt_atend_medico is null and :new.dt_atend_medico is not null)
		or (:old.dt_atend_medico is not null and :new.dt_atend_medico is null)	)) then

		select 	obter_valor_dominio(17, :new.ie_clinica) ds_clinica,
			obter_desc_queixa(:new.nr_seq_queixa) ds_sintoma_paciente,
			obter_estab_id_pfcs(:new.cd_estabelecimento) cd_cgc,
			coalesce(obter_triagem_atendimento(:new.nr_atendimento, 'S'),pfcs_get_severity_score(:new.nr_seq_triagem)) cd_escala_triagem,
			obter_atepacu_paciente(:new.nr_atendimento, 'IAA')
		into	ds_clinica_w,
			ds_sintoma_paciente_w,
			cd_cgc_w,
			cd_escala_triagem_w,
			nr_seq_interno_w
		from 	dual;

		if(:new.dt_fim_triagem is not null) then
		   ie_status_w := 'triaged';       
		end if;

		if(:new.dt_atend_medico is not null) then
		   ie_status_w := 'triaged';       
		end if;

		if(:new.dt_inicio_observacao is not null and :new.dt_fim_observacao is null)then
			ie_tipo_atendimento_w := 99;
			ie_status_w := 'in-progress'; 
		end if;

		if(:new.dt_cancelamento is not null) then
			ie_status_w := 'cancelled';
		end if;

		pfcs_int_encounter(:new.nr_atendimento, ie_status_w, coalesce(ie_tipo_atendimento_w,:new.ie_tipo_atendimento), :new.ie_clinica, ds_clinica_w, :new.cd_pessoa_fisica, :new.dt_entrada, :new.dt_alta,ds_sintoma_paciente_w,:new.cd_medico_resp, :new.cd_procedencia, null,cd_cgc_w, cd_escala_triagem_w, :new.dt_previsto_alta,	:new.cd_estabelecimento, null, null, null, wheb_usuario_pck.get_nm_usuario, 'N');

		if(ie_status_w = 'cancelled' and :new.ie_paciente_isolado = 'S')then
			pfcs_int_special_request('SR107'||:new.nr_atendimento, 'SR107', OBTER_EXPRESSAO_IDIOMA(292257), 'inactive', sysdate, :new.cd_pessoa_fisica, :new.nr_atendimento,  wheb_usuario_pck.get_nm_usuario, 'N');
		end if;

		-- Alta planejada
		if(:old.dt_alta_medico is null and :new.dt_alta_medico is not null) or (:old.dt_previsto_alta is null and :new.dt_previsto_alta is not null) or (:old.dt_previsto_alta is not null and :new.dt_previsto_alta is null) or (:old.dt_previsto_alta <> :new.dt_previsto_alta)then
			ie_status_alta_w := 'active';
			ds_status_alta_w := 'plan';
			DT_PREVISTO_ALTA_w := :new.DT_PREVISTO_ALTA;
		-- Estorno planejada
		elsif (:old.dt_alta_medico is not null) and (:new.dt_alta_medico is null)then
			ie_status_alta_w := 'revoked';
			ds_status_alta_w := 'plan';
		-- Alta realizada
		elsif(:old.dt_alta is null) and (:new.dt_alta is not null)then
			ie_status_alta_w := 'completed';
			ds_status_alta_w := 'order';
		-- Estorno da alta
		elsif(:old.dt_alta is not null) and (:new.dt_alta is null)then
			ie_status_alta_w := 'revoked';
			ds_status_alta_w := 'order';
		end if;


		if(nr_seq_interno_w > 0) then
			select 	REPLACE(a.cd_setor_atendimento||'@'||substr(obter_nome_setor(a.cd_setor_atendimento),1,100),'.',' ')||'.'||REPLACE(a.cd_unidade_basica,'.',' ')||'.'||REPLACE(a.cd_unidade_compl,'.',' ') nome_setor_leito
			into 	 nm_setor_leito_w
			from 	atend_paciente_unidade a
			where	a.nr_seq_interno = nr_seq_interno_w
			and 	a.nr_atendimento = :new.nr_atendimento;
		end if;

		if(ie_status_alta_w is not null) and (ds_status_alta_w is not null) then
			pfcs_int_service_request(:new.nr_atendimento, ie_status_alta_w, ds_status_alta_w, 'E0405', 'Discharge', :new.cd_pessoa_fisica, nm_setor_leito_w, cd_cgc_w, wheb_usuario_pck.get_nm_usuario, 'N',:new.nr_atend_alta,DT_PREVISTO_ALTA_w);
		else
			-- Admissao planejada
			if(:new.ie_tipo_atendimento in (8))then
				ie_status_admissao_w	:= 'active';
				ds_status_admissao_w	:= 'plan';

			-- Admissao realizada
			elsif(:new.ie_tipo_atendimento not in (8))then
				ie_status_admissao_w	:= 'completed';
				ds_status_admissao_w	:= 'order';
			end if;

			-- Estorno da adimissao
			if(:old.dt_cancelamento is null and :new.dt_cancelamento is not null)then
				ie_status_admissao_w	:= 'revoked';
				ds_status_admissao_w	:= 'order';
			end if;

			if(ie_status_admissao_w is not null) and (ds_status_admissao_w is not null) and (:new.nr_atend_alta is null) then
				pfcs_int_service_request(:new.nr_atendimento, ie_status_admissao_w, ds_status_admissao_w, 'E0401', 'Request for Bed', :new.cd_pessoa_fisica, nm_setor_leito_w, cd_cgc_w, wheb_usuario_pck.get_nm_usuario, 'N',:new.nr_atend_alta,coalesce(DT_PREVISTO_ALTA_w,sysdate));
			elsif(ie_status_admissao_w is not null) and (ds_status_admissao_w is not null) and (:new.nr_atend_alta is not null) then
				pfcs_int_service_request(:new.nr_atendimento, ie_status_admissao_w, ds_status_admissao_w, 'E0402', 'Request for Bed', :new.cd_pessoa_fisica, nm_setor_leito_w, cd_cgc_w, wheb_usuario_pck.get_nm_usuario, 'N',:new.nr_atend_alta,coalesce(DT_PREVISTO_ALTA_w,sysdate));
			end if;
		end if;

	elsif (deleting and param_version_pfcs_w is not null) then

		select 	obter_valor_dominio(17, :old.ie_clinica)	ds_clinica,
				obter_desc_queixa(:old.nr_seq_queixa) ds_sintoma_paciente,
				 obter_estab_id_pfcs(:old.cd_estabelecimento) cd_cgc,
				obter_atepacu_paciente(:old.nr_atendimento, 'IAA')
		into	ds_clinica_w,
				ds_sintoma_paciente_w,
				cd_cgc_w,
				nr_seq_interno_w
		from dual;

		pfcs_int_encounter(:old.nr_atendimento, 'cancelled', :old.ie_tipo_atendimento, :old.ie_clinica, ds_clinica_w, :old.cd_pessoa_fisica, :old.dt_entrada,
		:old.dt_alta, ds_sintoma_paciente_w, :old.cd_medico_resp, :old.cd_procedencia, null, cd_cgc_w, null, :old.dt_previsto_alta,	:old.cd_estabelecimento, null, null, null, wheb_usuario_pck.get_nm_usuario, 'N');

		if(:old.ie_paciente_isolado = 'S')then
			pfcs_int_special_request('SR107'||:old.nr_atendimento, 'SR107', OBTER_EXPRESSAO_IDIOMA(292257), 'inactive', sysdate, :old.cd_pessoa_fisica, :old.nr_atendimento,  wheb_usuario_pck.get_nm_usuario, 'N');
		end if;

		if(nr_seq_interno_w > 0) then
			select 	REPLACE(a.cd_setor_atendimento||'@'||substr(obter_nome_setor(a.cd_setor_atendimento),1,100),'.',' ')||'.'||REPLACE(a.cd_unidade_basica,'.',' ')||'.'||REPLACE(a.cd_unidade_compl,'.',' ') nome_setor_leito
			into 	nm_setor_leito_w
			from 	atend_paciente_unidade a
			where	a.nr_seq_interno = nr_seq_interno_w
			and 	a.nr_atendimento = :old.nr_atendimento;
		end if;

			pfcs_int_service_request(:old.nr_atendimento, 'revoked', 'order', 'E0401', 'Request for Bed', :old.cd_pessoa_fisica, nm_setor_leito_w, cd_cgc_w, wheb_usuario_pck.get_nm_usuario, 'N',:new.nr_atend_alta,coalesce(DT_PREVISTO_ALTA_w,sysdate));

	end if;

	if(inserting) or ((updating) and (nvl(:old.ie_paciente_isolado,'N') <> nvl(:new.ie_paciente_isolado,'N')))then
		if(nvl(:new.ie_paciente_isolado,'N') = 'S')then
			ie_status_request_w := 'active';
		end if;
		pfcs_int_special_request('SR107'||:new.nr_atendimento, 'SR107', OBTER_EXPRESSAO_IDIOMA(292257), ie_status_request_w, sysdate, :new.cd_pessoa_fisica, :new.nr_atendimento,  wheb_usuario_pck.get_nm_usuario, 'N');
	end if;



end if;

commit;

END;

ALTER TRIGGER "TASY"."INT_PFCS_ATENDIMENTO_PACIENTE" ENABLE

  CREATE OR REPLACE EDITIONABLE TRIGGER "TASY"."ATENDIMENTO_PACIENTE_BEFINS" 

before insert on atendimento_paciente
for each row

declare

qt_regra_medico_atend_w		number(10,0);
qt_regra_medico_atend_assist_w	number(10,0);
qt_regra_medico_atend_categ_w	number(10);
qt_regra_medico_atend_categ_ww	number(10);
ie_pf_credenciada_w		varchar2(2);
ie_corpo_clinico_w			varchar2(1);
qt_medico_w			number(10);
ie_forma_usuario_intern_w		varchar2(1);
qt_idade_w			number(10);
nr_seq_triagem_prioridade_w		number(10);
nr_seq_classif_w			number(10);
ds_classificacao_w			varchar2(200);
ie_permite_w			varchar2(10);
ie_responsavel_nao_medico_w	varchar2(10);
ie_calcula_data_prev_w		varchar2(10);
nm_medico_w			varchar2(255);
ds_senha_internet_w		atend_senha_internet.ds_senha%type;
reg_integracao_w			gerar_int_padrao.reg_integracao;
ie_case varchar2(1);
nr_seq_permissao_w 		medico_permissao_unica.nr_sequencia%type;
dt_fim_permissao_w			medico_permissao_unica.dt_final%type;
qt_minutos_permissao_w		number(10);
allow_future_date_w		funcao_param_usuario.vl_parametro%type;
qt_reg_ww number(10);
ie_sexo_w  				pessoa_fisica.ie_sexo%type;
nr_dias_retroativos_w number(10);
dt_entrada_W date;
pessoa_fisica_triagem_w number(10);
nm_pf_atend_w	varchar2(255);
nm_pf_triagem_w	varchar2(255);

cursor c01 is
	select	nr_sequencia
	from	triagem_classif_prioridade
	where	ie_situacao = 'A'
	and	qt_idade_w between	obter_idade_prioridade(nr_sequencia,'MIN') and obter_idade_prioridade(nr_sequencia,'MAX')
	and	((	qt_idade_min is not null
			and	qt_idade_max is not null) or

		((qt_idade_min_mes	is not null) and
		(qt_idade_max_mes	is not null)) or

		(qt_idade_min_dia	is not null and qt_idade_max_dia is not null))
	and	(nvl(cd_estabelecimento,:new.cd_estabelecimento) = :new.cd_estabelecimento)
  and	(nvl(ie_sexo,'A') = 'A' or nvl(ie_sexo,'A') = ie_sexo_w)
	order by nr_seq_prioridade desc;

function obter_qt_atendimento(
		nr_seq_episodio_p		number,
		nr_atendimento_p	number) return number is

qt_reg_w	number(10);

pragma autonomous_transaction;
begin
	select	count(1)
	into	qt_reg_w
	from	atendimento_paciente
	where	nr_seq_episodio = nr_seq_episodio_p
	and	nr_atendimento <> nr_atendimento_p;

	return qt_reg_w;
end obter_qt_atendimento;


begin
	if	(wheb_usuario_pck.get_ie_executar_trigger	= 'N')  then
		goto final;
	end if;

	abort_temp_retro_param1245(:new.DT_ATUALIZACAO_NREC, :new.DT_ENTRADA);

	select 	max(b.cd_pessoa_fisica)
	into	pessoa_fisica_triagem_w
	from    triagem_pronto_atend b
	where   :new.NR_SEQ_PAC_SENHA_FILA = b.nr_seq_fila_senha;

	select 	substr(obter_nome_pf(:new.cd_pessoa_fisica),1,60),
			substr(obter_nome_pf(pessoa_fisica_triagem_w),1,60)
	into	nm_pf_atend_w,
			nm_pf_triagem_w
	from 	dual;


	if(pessoa_fisica_triagem_w is not null and :new.cd_pessoa_fisica <> pessoa_fisica_triagem_w)THEN
		wheb_mensagem_pck.exibir_mensagem_abort(1257226,'CD_PESSOA_ATEND='||:new.cd_pessoa_fisica||';DS_PESSOA_ATEND='||nm_pf_atend_w||';CD_PESSOA_TRIAGEM_PA='||pessoa_fisica_triagem_w||';DS_PESSOA_TRIAGEM_PA='||nm_pf_triagem_w);
	end if;

	if(nvl(pkg_i18n.get_user_locale, 'pt_BR') in ('de_DE', 'de_AT'))then

		cancelar_atend_controle(:new.cd_pessoa_fisica, 'N');

		Obter_Param_Usuario(916, 1206, obter_perfil_ativo, :new.nm_usuario, wheb_usuario_pck.get_cd_estabelecimento, allow_future_date_w);

		if(nvl(allow_future_date_w, 'N') = 'N' and ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(:new.dt_chegada_paciente) > ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(sysdate))then
			wheb_mensagem_pck.exibir_mensagem_abort(1083786);
		end if;                                                                                 
		if(nvl(allow_future_date_w, 'N') = 'N' and :new.dt_chegada_paciente is not null and (ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(:new.dt_chegada_paciente) <> ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(:new.dt_entrada) and ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(:new.dt_entrada) > ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(sysdate))) then
			wheb_mensagem_pck.exibir_mensagem_abort(1083769);
		end if;

	end if;

	/* acdalfovo em 25/07/2018 - os 1602534 */

	/*parametro [144] "tempo em minutos para permissao unica do medico apos abertura do primeiro atendimento"  (funcao: cadastro medico)*/
	qt_minutos_permissao_w := nvl(obter_valor_param_usuario(4, 144, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento),0);
	ie_corpo_clinico_w := obter_se_corpo_clinico(:new.cd_medico_resp);

	if	(nvl(ie_corpo_clinico_w,'N') = 'N' and
		qt_minutos_permissao_w > 0) then
		begin


		select	max(nr_sequencia)
		into	nr_seq_permissao_w
		from 	medico_permissao_unica
		where	dt_liberacao is not null
		and		cd_pessoa_fisica = :new.cd_medico_resp;

		if (nr_seq_permissao_w is not null) then

			select 	max(nr_sequencia),
				max(dt_final)
			into	nr_seq_permissao_w,
				dt_fim_permissao_w
			from	medico_permissao_unica
			where	dt_inativacao is null
			and	dt_liberacao is not null
			and	:new.dt_entrada between dt_inicio and nvl(dt_final,:new.dt_entrada)
			and	cd_pessoa_fisica = :new.cd_medico_resp;

			/*se possui permissao unica ativa e liberada, definir a data final de acordo com o parametro e autorizar medico responsavel*/
			if	(nr_seq_permissao_w is not null and
				dt_fim_permissao_w is null) then

				update 	medico_permissao_unica
				set 	dt_final = :new.dt_entrada + qt_minutos_permissao_w/1440
				where 	nr_sequencia = nr_seq_permissao_w;

			end if;

			if	(nr_seq_permissao_w is null) then
				wheb_mensagem_pck.exibir_mensagem_abort(1034265);
				--o medico responsavel pelo atendimento nao possui permissao para efetuar atendimentos.
			end if;
		end if;
		end;
	end if;
	/* fim acdalfovo em 25/07/2018 - os 1602534 */

	select	nvl(max(ie_forma_usuario_intern),'N')
	into	ie_forma_usuario_intern_w
	from	parametro_atendimento
	where	cd_estabelecimento	= :new.cd_estabelecimento;

	if	(ie_forma_usuario_intern_w = 'U') and
		(:new.ie_tipo_atendimento = 1) and	
		(:new.nm_usuario_intern is null) then
		begin	
		:new.nm_usuario_intern	:= :new.nm_usuario;	
		:new.dt_usuario_intern	:= sysdate;		
		end;
	end if;

	select	nvl(max(obter_valor_param_usuario(916, 789, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento)),'N')
	into	ie_responsavel_nao_medico_w
	from 	dual;

	select	nvl(max(obter_valor_param_usuario(916, 953, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento)),'S')
	into	ie_calcula_data_prev_w
	from 	dual;

	select	count(*)
	into	qt_medico_w
	from	medico
	where	cd_pessoa_fisica = :new.cd_medico_resp; 

	if	(nvl(ie_responsavel_nao_medico_w,'N') = 'S') and
		(qt_medico_w = 0) then
		begin
		select	nvl(max(obter_se_responsavel_atend(obter_perfil_ativo,:new.cd_medico_resp,0,0)),0)
		into	ie_permite_w
		from	dual;

		if	(ie_permite_w = 'N') then
			begin
			wheb_mensagem_pck.exibir_mensagem_abort(196872);
			--o conselho da pessoa digitada nao esta liberado para ser responsavel do atendimento
			end;
		end if;	
		end;
	end if;


	if (nvl(pkg_i18n.get_user_locale, 'pt_BR') <> 'es_CO') then
		if	(qt_medico_w = 0) and
			(:new.cd_medico_resp is not null) and
			((nvl(ie_responsavel_nao_medico_w,'N') = 'N') or ((qt_medico_w = 0) and (nvl(ie_responsavel_nao_medico_w,'N') = 'S') and (ie_permite_w = 'N'))) then
			wheb_mensagem_pck.exibir_mensagem_abort(196873);
			--o codigo de medico digitado nao esta cadastrado na tabela de medico
		end if;
	end if;

	consistir_impedimento_pf(:new.cd_medico_resp,'EUP',:new.nm_usuario);

	if	(:new.cd_medico_atendimento is null) then
		:new.cd_medico_atendimento	:= :new.cd_medico_resp;
	end if;	

	ie_case := obter_uso_case(:new.nm_usuario);

	/* elemar 26/07/2004 */
	if	(:new.ds_senha is null and ie_case != 'S') and (NVL(pkg_i18n.get_user_locale, 'pt_BR') = 'pt_BR') then
		:new.ds_senha := gerar_senha_atendimento(:new.ie_tipo_atendimento, :new.nr_seq_regra_funcao, :new.cd_pessoa_fisica, 'A');
	end if;

	if	(:new.ds_senha_internet is null)  then
		ds_senha_internet_w	:= gerar_senha_atendimento(:new.ie_tipo_atendimento, :new.nr_seq_regra_funcao, :new.cd_pessoa_fisica, 'I');		
		if	(ds_senha_internet_w is not null) then
			gerar_senha_internet(:new.nr_atendimento, null, null, null, ds_senha_internet_w,'');
			:new.ds_senha_internet	:= ds_senha_internet_w;
		end if;
	end if;

	/* marcus 23/12/2004 */
	:new.dt_alta_interno	:= to_date('30/12/2999','dd/mm/yyyy');

	if	(:new.ie_fim_conta is null) then
		:new.ie_fim_conta	:= 'A';
	end if;

	/* rafael em 3/3/8 os82466 */
	ie_corpo_clinico_w := obter_se_corpo_clinico(:new.cd_medico_resp);
	if	(ie_corpo_clinico_w = 'N') and
		(:new.ie_tipo_atendimento = 1) then
		consistir_credenciamento_pf(nvl(:new.cd_estabelecimento,0), nvl(obter_especialidade_medico(:new.cd_medico_resp,'C'),0), :new.cd_pessoa_fisica, nvl(:new.dt_alta,sysdate), :new.cd_medico_resp, :new.nr_atendimento,:new.nr_atendimento_mae, ie_pf_credenciada_w);	
		if	(ie_pf_credenciada_w = 'N') then

			select 	substr(obter_nome_pf(:new.cd_medico_resp),1,60)
			into	nm_medico_w
			from 	dual;

			wheb_mensagem_pck.exibir_mensagem_abort(196874,'NM_MEDICO=' || nm_medico_w);
			--o medico #@nm_medico#@ nao esta credenciado a realizar este atendimento.
		end if;
	else
		ie_pf_credenciada_w	:= 'S';
		if	(obter_valor_param_usuario(916, 265, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento) = 'S') then
			consistir_credenciamento_pf(nvl(:new.cd_estabelecimento,0), nvl(obter_especialidade_medico(:new.cd_medico_resp,'C'),0), :new.cd_pessoa_fisica, nvl(:new.dt_alta,sysdate), :new.cd_medico_resp, :new.nr_atendimento, :new.nr_atendimento_mae, ie_pf_credenciada_w);
			/*if	(ie_pf_credenciada_w = 'N') then
				rase_application_error(-20011,'O medico ' || substr(obter_nome_pf(:new.cd_medico_resp),1,60) || ' nao esta credenciado a realizar este atendimento.#@#@');
			end if;*/
		end if;
	end if;
	/* fim rafael em 3/3/8 os82466 */

	/* oraci em 10/09/2007 os68160 */
	select	count(*)
	into	qt_regra_medico_atend_w
	from	regra_medico_atend
	where	cd_estabelecimento	= :new.cd_estabelecimento
	and	ie_tipo_atendimento	= :new.ie_tipo_atendimento
	and	ie_corpo_clinico = 'S'
	and 	obter_se_corpo_clinico(:new.cd_medico_resp) = 'N';

	select	count(*)
	into	qt_regra_medico_atend_assist_w
	from	regra_medico_atend
	where	cd_estabelecimento	= :new.cd_estabelecimento
	and	ie_tipo_atendimento	= :new.ie_tipo_atendimento
	and	ie_corpo_assistencial = 'S'
	and	obter_se_corpo_assist(:new.cd_medico_resp) = 'N';


	select	count(*)
	into	qt_regra_medico_atend_categ_w
	from	regra_medico_atend a,
		regra_medico_atend_categ b
	where	a.nr_sequencia	= b.nr_seq_regra
	and	a.cd_estabelecimento	= :new.cd_estabelecimento
	and	a.ie_tipo_atendimento	= :new.ie_tipo_atendimento
	and	b.nr_seq_categoria	= obter_dados_medico(:new.cd_medico_resp,'CAT');


	select	count(*)
	into	qt_regra_medico_atend_categ_ww
	from	regra_medico_atend a,
		regra_medico_atend_categ b
	where	a.nr_sequencia	= b.nr_seq_regra
	and	a.cd_estabelecimento	= :new.cd_estabelecimento
	and	a.ie_tipo_atendimento	= :new.ie_tipo_atendimento
	and	b.nr_seq_categoria	= obter_dados_medico(:new.cd_medico_resp,'CAT');


	if	((qt_regra_medico_atend_w > 0) or (qt_regra_medico_atend_assist_w > 0)) and
		(ie_pf_credenciada_w <> 'S')  or
		((qt_regra_medico_atend_categ_w	> 0) or (qt_regra_medico_atend_categ_ww	>0)) then /* rafael em 3/3/8 os77352 incluida esta linha */
		wheb_mensagem_pck.exibir_mensagem_abort(196875);
		--medico nao pode ser responsavel pelo atendimento. verificar regra medico atendimento.
	end if;

	/* dalcastagne em 18/02/2008 os 83134*/
	if	((ie_calcula_data_prev_w = 'S') and (nvl(:new.qt_dias_prev_inter,0) > 0)) then
		:new.dt_previsto_alta	:= :new.dt_entrada + nvl(:new.qt_dias_prev_inter,0);
	else
		:new.dt_previsto_alta	:= :new.dt_previsto_alta;
	end if;


	if	(obter_se_perm_pf_classif(916,0,:new.cd_pessoa_fisica,sysdate)	= 'N') then



		nr_seq_classif_w	:= obter_se_perm_pf_classif(916,0,:new.cd_pessoa_fisica,sysdate,'SEQ');

		select	max(ds_classificacao)
		into	ds_classificacao_w
		from	classif_pessoa
		where	nr_sequencia	= nr_seq_classif_w;

		wheb_mensagem_pck.exibir_mensagem_abort(196876,'DS_CLASSIFICACAO=' || ds_classificacao_w);
		--esse paciente possui a classificacao #@ds_classificacao#@ que nao e permitida nesta funcao.
	end if;

	if	(:new.cd_pessoa_fisica is not null) and
		(:new.nr_seq_triagem_prioridade is null) then
		qt_idade_w	:= obter_idade_pf(:new.cd_pessoa_fisica,sysdate,'DIA');
	  ie_sexo_w	:= nvl(Obter_Sexo_PF(:new.cd_pessoa_fisica,'C'),'I');
		open c01;
		loop
		fetch c01 into	
			nr_seq_triagem_prioridade_w;
		exit when c01%notfound;
		end loop;
		close c01;

		if	(nr_seq_triagem_prioridade_w	is not null) then
			:new.nr_seq_triagem_prioridade	:= nr_seq_triagem_prioridade_w;
		end if;
	end if;

	if ('00/00/0000 00:00:00' = to_char(:new.dt_previsto_alta,'dd/mm/yyyy hh24:mi:ss')) then
		:new.dt_previsto_alta := null;
	end if;

	if (obter_funcao_ativa <> 381) then
		:new.ie_nivel_atencao := wheb_assist_pck.get_nivel_atencao_perfil;
	end if;
	:new.cd_setor_usuario_atend := wheb_usuario_pck.get_cd_setor_atendimento;

	if	(:new.nr_seq_tipo_admissao_fat is not null) then
		consiste_tipo_visita_atend(nr_atendimento_p => :new.nr_atendimento, 
					   cd_pessoa_fisica_p => :new.cd_pessoa_fisica,
					   nr_seq_tipo_admissao_fat_p => :new.nr_seq_tipo_admissao_fat,
					   nr_seq_episodio_p => :new.nr_seq_episodio,
					   dt_entrada_p => :new.dt_entrada);
	end if;

	if (:new.nr_seq_tipo_admissao_fat is not null and :new.ie_tipo_atendimento is null and nvl(pkg_i18n.get_user_locale, 'pt_BR') in ('de_DE', 'de_AT')) then
		:new.ie_tipo_atendimento := nvl(obter_tipo_atend_admissao(:new.nr_seq_tipo_admissao_fat), :new.ie_tipo_atendimento);
	end if;

	if (NVL(pkg_i18n.get_user_locale, 'pt_BR') <> 'pt_BR') and (:new.ds_senha is not null) then
		:new.ds_senha := null;
	end if;

	<<final>>

	qt_reg_ww := 0;

end;

