	where	a.nr_sequencia 		= b.nr_seq_regra(+)
	and	a.cd_estabelecimento	= :new.cd_estabelecimento
	and	a.ie_evento_disp	= 'ALT'
	and	nvl(cd_motivo_alta,nvl(:new.cd_motivo_alta,0))			= nvl(:new.cd_motivo_alta,0)
	and	qt_idade_w between nvl(qt_idade_min,0)	and nvl(qt_idade_max,9999)
	and	nvl(b.ie_carater_inter_sus,nvl(:new.ie_carater_inter_sus,0)) 	= nvl(:new.ie_carater_inter_sus,'0')
	and	nvl(b.ie_tipo_atendimento,nvl(:new.ie_tipo_atendimento,0)) 	= nvl(:new.ie_tipo_atendimento,'0')
	and	obter_se_convenio_rec_alerta(cd_convenio_w, a.nr_sequencia) = 'S'
	and	obter_se_sms_setor_alerta(:new.nr_atendimento,a.nr_sequencia) = 'S'
	and	(obter_classif_regra(a.nr_sequencia,nvl(obter_classificacao_pf(:new.cd_pessoa_fisica),0)) = 'S')
	and	nvl(b.ie_clinica,nvl(:new.ie_clinica,0)) = nvl(:new.ie_clinica,'0')
	and	nvl(a.cd_medico,nvl(:new.cd_medico_resp,'0')) = nvl(:new.cd_medico_resp,'0')
	and	nvl(a.ie_situacao,'A') = 'A'
	and ((a.ie_sexo is null) or  (a.ie_sexo = nvl(obter_sexo_pf(:new.cd_pessoa_fisica,'C'),'I')));	

