procedure atualiza_Data_obito(dt_obito_p date, cd_pessoa_fisica_p varchar2 ) is
dt_obito_ww          date;
begin

	select	max(dt_obito)
	into	dt_obito_ww
	from	pessoa_fisica
	where	cd_pessoa_fisica	= cd_pessoa_fisica_p;

	if  (dt_obito_ww is null) or
		(obter_valor_param_usuario(3111, 342, obter_perfil_ativo, nvl(obter_usuario_ativo,:new.nm_usuario), :new.cd_estabelecimento) = 'N') then

		update pessoa_fisica pf
		set pf.dt_obito = dt_obito_p,
		pf.nm_usuario  		= :new.nm_usuario,
		pf.dt_atualizacao  	= sysdate
		where	pf.cd_pessoa_fisica	= cd_pessoa_fisica_p;

	end if;

end;

begin

	abort_temp_retro_param1245(:new.DT_ATUALIZACAO_NREC, :new.DT_ENTRADA);

	if	(wheb_usuario_pck.get_ie_executar_trigger	= 'N')  then
		goto final;
	end if;

	obter_param_usuario(3111, 341, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_parametro_atend_pac_w);

	if  (:new.dt_saida_real < :old.dt_entrada) and 
		(ie_parametro_atend_pac_w = 'N')  then
	wheb_mensagem_pck.exibir_mensagem_abort(1236128);
	end if;

	ds_sep_bv_w := obter_separador_bv;

	obter_param_usuario(916, 990, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_perm_data_menor_nasc_w);
	dt_nasc_paciente_w := to_date(obter_dados_pf(:new.cd_pessoa_fisica,'DN'),'dd/mm/yyyy hh24:mi:ss');

	begin

	select	substr(nvl(obter_nome_pf(:new.cd_medico_resp),''),1,255)
	into	nm_medico_resp_w
	from	dual;

	exception
	when others then
		nm_medico_resp_w	 := '';
	end;

	select max(nr_seq_interno)
	into	nr_seq_atend_w
	from	atend_paciente_unidade
	where	nr_atendimento = :new.nr_atendimento;

	if (nvl(:old.nr_seq_classif_esp, 0) <> nvl(:new.nr_seq_classif_esp, 0)) then
	   insert_atend_unid_classif_esp(:old.nr_seq_classif_esp, :new.nr_seq_classif_esp, :new.nr_atendimento, null, :new.nm_usuario);
	end if;

	if(nvl(pkg_i18n.get_user_locale, 'pt_BR') in ('de_DE', 'de_AT'))then

		Obter_Param_Usuario(916, 1206, obter_perfil_ativo, :new.nm_usuario, wheb_usuario_pck.get_cd_estabelecimento, allow_future_date_w);

		if(:old.dt_chegada_paciente is not null and :new.dt_chegada_paciente is null)then
			wheb_mensagem_pck.exibir_mensagem_abort(1083783);
		end if;

		if(nvl(allow_future_date_w, 'N') = 'N' and ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(:new.dt_chegada_paciente) > ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(sysdate))then
