	obter_param_usuario(916, 195, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_trocar_medico_w);

	if	((ie_trocar_medico_w = 'S') and
		 (:old.cd_medico_atendimento <> :new.cd_medico_atendimento) and
		 (:new.cd_medico_resp <> :new.cd_medico_atendimento)) then
		:new.cd_medico_resp	:= :new.cd_medico_atendimento;
	end if;

	/* Dalcastagne em 18/02/2008 OS 83134 - Beckhauser em 13/07/2012 OS 462029*/
	obter_param_usuario(916, 953, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_calcula_data_prev_w);

	if	(ie_calcula_data_prev_w = 'S') and (nvl(:new.qt_dias_prev_inter,0) > 0) and (nvl(:old.qt_dias_prev_inter,0) <> nvl(:new.qt_dias_prev_inter,0)) then
		:new.dt_previsto_alta	:= :new.dt_entrada + nvl(:new.qt_dias_prev_inter,0);
	else
		:new.dt_previsto_alta	:= :new.dt_previsto_alta;
	end if;

	/*Atualizar o status do atendimento no PA */
	if 	(:new.dt_alta is not null) then
		:new.ie_status_pa := 'AL';
		gravar_atend_status_pa(:new.nr_atendimento,'AL',:new.nm_usuario);
	end if;

	if 	(:new.dt_lib_medico is not null) and (:old.dt_lib_medico is null) then
		:new.ie_status_pa := 'LM';
		gravar_atend_status_pa(:new.nr_atendimento,'LM',:new.nm_usuario);
	elsif	(:new.dt_medicacao is not null) and (:old.dt_medicacao is null) then
		:new.ie_status_pa := 'PA';
		gravar_atend_status_pa(:new.nr_atendimento,'PA',:new.nm_usuario);
	elsif	(:new.dt_fim_consulta is not null) and (:old.dt_fim_consulta is null) then
		:new.ie_status_pa := 'FC';
		gravar_atend_status_pa(:new.nr_atendimento,'FC',:new.nm_usuario);
	elsif	(:new.dt_atend_medico is not null) and (:old.dt_atend_medico is null) then
		:new.ie_status_pa := 'IC';
		gravar_atend_status_pa(:new.nr_atendimento,'IC',:new.nm_usuario);
	elsif	(:new.dt_chamada_paciente is not null) and (:old.dt_chamada_paciente is null) then
		:new.ie_status_pa := 'CP';
		gravar_atend_status_pa(:new.nr_atendimento,'CP',:new.nm_usuario);
	elsif	(:new.dt_fim_triagem is not null) and (:old.dt_fim_triagem is null) then
		:new.ie_status_pa := 'FT';
		gravar_atend_status_pa(:new.nr_atendimento,'FT',:new.nm_usuario);
	elsif	(:new.dt_inicio_atendimento is not null) and (:old.dt_inicio_atendimento is null) then
		:new.ie_status_pa := 'TR';
		gravar_atend_status_pa(:new.nr_atendimento,'TR',:new.nm_usuario);
	elsif	(:new.dt_reavaliacao_medica is not null) and (:old.dt_reavaliacao_medica is null) then
		:new.ie_status_pa := 'RM';
		gravar_atend_status_pa(:new.nr_atendimento,'RM',:new.nm_usuario);
	elsif	(:new.dt_liberacao_enfermagem is not null) and (:old.dt_liberacao_enfermagem is null) then
		:new.ie_status_pa := 'LE';
		gravar_atend_status_pa(:new.nr_atendimento,'LE',:new.nm_usuario);
	end if;

	if 	(:new.ds_senha is null) and (NVL(pkg_i18n.get_user_locale, 'pt_BR') = 'pt_BR') then /*Bruna OS104731*/
		:new.ds_senha := gerar_senha_atendimento(:new.ie_tipo_atendimento, :new.nr_seq_regra_funcao, :new.cd_pessoa_fisica, 'A');
	end if;

	if (obter_funcao_ativa = 916) and
	   (:new.ie_tipo_atendimento <> :old.ie_tipo_atendimento) then

		select 	count(1)
		into	ds_senha_w
		from	atend_senha_internet
		where	nr_atendimento 	= :new.nr_atendimento;

		if 	((ds_senha_w is not null) or (ds_senha_w  > 0 ))then
			if	(:new.ds_senha_internet is null)  then
				ds_senha_internet_w	:= gerar_senha_atendimento(:new.ie_tipo_atendimento, :new.nr_seq_regra_funcao, :new.cd_pessoa_fisica, 'I');
				if	(ds_senha_internet_w is not null) then
					gerar_senha_internet(:new.nr_atendimento, null, null, null, ds_senha_internet_w,'');
					:new.ds_senha_internet	:= ds_senha_internet_w;
				end if;
			end if;
		end if;
	end if;

	if	(:new.dt_alta is not null) and
		(:old.dt_alta is null) then
		/*
		open C03;
		loop
		fetch C03 into
			nr_seq_evento_w;
		exit when C03%notfound;
			begin
			gerar_evento_paciente_trigger(nr_seq_evento_w,:new.nr_atendimento,:new.cd_pessoa_fisica,null,:new.nm_usuario);
			end;
		end loop;
		close C03;
		*/
		gravar_historico_alta(:new.nr_atendimento,'A',sysdate,:new.cd_motivo_alta,:new.ds_obs_alta,:new.nm_usuario,:new.dt_alta);

	elsif	(:new.dt_alta is null) and
		(:old.dt_alta is not null) then
		gravar_historico_alta(:new.nr_atendimento,'E',sysdate,null,:new.ds_obs_alta,:new.nm_usuario);
	end if;

	select nvl(max(ie_historico_conta),'N')
	into	ie_historico_conta_w
	from	parametro_faturamento
	where	cd_estabelecimento	= :new.cd_estabelecimento;

	select	substr(max(module||' - ' || machine||' - ' || program|| ' - ' || osuser|| ' - ' || terminal),1,255)
	into	ds_module_log_w
	from	v$session
	where	audsid = (select userenv('sessionid') from dual);

	if	(ie_historico_conta_w		= 'S') and
		((:old.dt_fim_conta 	is null	and (:new.dt_fim_conta 	is not null)) or
		(:new.dt_fim_conta is null and :old.dt_fim_conta is not null) or
	  (:new.dt_alta is not null) and (:old.dt_alta is null))  then
		open c04;
		loop
		fetch c04 into
			nr_interno_conta_w,
			cd_convenio_w,
			nr_seq_protocolo_w;
		exit when c04%notfound;
			begin

			nr_nivel_anterior_w := null;
			nr_nivel_atual_w := null;

			select	conta_paciente_hist_seq.nextval
			into	nr_sequencia_w
			from	dual;

			select	max(h.nr_sequencia)
			into nr_sequencia_conta_hist_w
			from	conta_paciente_hist h,
			conta_paciente c
			where	c.nr_interno_conta = nr_interno_conta_w
			and c.nr_interno_conta = h.nr_interno_conta;

			if (nr_sequencia_conta_hist_w is not null) then
				select	nr_nivel_atual
				into	nr_nivel_atual_w
				from	conta_paciente_hist
				where	nr_sequencia = nr_sequencia_conta_hist_w;
			end if;

			if (nr_nivel_atual_w = 2) then
				nr_nivel_anterior_w := nr_nivel_atual_w;
				nr_nivel_atual_w := 4;
			else
				nr_nivel_anterior_w := nr_nivel_atual_w;
			end if;	
				ds_call_stack_w	:= substr(dbms_utility.format_call_stack,1,1800);

			if(:new.dt_alta is not null and :old.dt_alta is null) then

				if (nr_nivel_atual_w is null and :old.dt_fim_conta is null) then
					nr_nivel_atual_w := 11;
				elsif (nr_nivel_atual_w is null and :old.dt_fim_conta is not null) then
					nr_nivel_atual_w := 12;
				end if;

				if (nr_nivel_anterior_w is null and :old.dt_fim_conta is null) then
					nr_nivel_anterior_w := 11;
				elsif (nr_nivel_anterior_w is null and :old.dt_fim_conta is not null) then
					nr_nivel_anterior_w := 12;
				end if;

				insert into conta_paciente_hist(
					nr_sequencia, dt_atualizacao, nm_usuario,
					vl_conta, nr_seq_protocolo, nr_interno_conta,
					nr_nivel_anterior, nr_nivel_atual, dt_referencia,
					nr_atendimento, cd_convenio, dt_conta_protocolo,
					cd_funcao, ds_module, ds_call_stack, ds_observacao)
				values	(
					nr_sequencia_w, sysdate, :new.nm_usuario,
					obter_valor_conta(nr_interno_conta_w,0), nr_seq_protocolo_w, nr_interno_conta_w,
					nr_nivel_anterior_w, nr_nivel_atual_w , ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(sysdate),
					:new.nr_atendimento, cd_convenio_w, null,
					obter_funcao_ativa, ds_module_log_w, ds_call_stack_w, obter_desc_expressao(612652));
			end if;

			if ((:old.dt_fim_conta 	is null	and (:new.dt_fim_conta 	is not null)) or
				(:new.dt_fim_conta is null and :old.dt_fim_conta is not null)) then
				select	conta_paciente_hist_seq.nextval
				into	nr_sequencia_w
				from	dual;
				insert into conta_paciente_hist(
					nr_sequencia, dt_atualizacao, nm_usuario,
					vl_conta, nr_seq_protocolo, nr_interno_conta,
					nr_nivel_anterior, nr_nivel_atual, dt_referencia,
					nr_atendimento, cd_convenio, dt_conta_protocolo,
					cd_funcao, ds_module, ds_call_stack)
				values	(
					nr_sequencia_w, sysdate, :new.nm_usuario,
					obter_valor_conta(nr_interno_conta_w,0), nr_seq_protocolo_w, nr_interno_conta_w,
					decode(to_char(:new.dt_fim_conta,'dd/mm/yyyy'),null,12,11), decode(to_char(:new.dt_fim_conta,'dd/mm/yyyy'),null,11,12) , ESTABLISHMENT_TIMEZONE_UTILS.startOfDay(sysdate),
					:new.nr_atendimento, cd_convenio_w, null,
					obter_funcao_ativa, ds_module_log_w, ds_call_stack_w);
			end if;
			end;
			end loop;
			close c04;
	end if;

	if	(nvl(:new.ie_probabilidade_alta,'XX') <> nvl(:old.ie_probabilidade_alta,'XX')) then

		update	atend_paciente_prob_alta
		set 	dt_fim_prev = sysdate
		where	nr_atendimento = :new.nr_atendimento
		and	dt_fim_prev is null;

		if	(:new.ie_probabilidade_alta is not null) then

			insert into atend_paciente_prob_alta (	nr_sequencia,
								dt_atualizacao,
								nm_usuario,
								dt_atualizacao_nrec,
								nm_usuario_nrec,
								ie_probabilidade_alta,
								dt_previsao_alta,
								dt_inicio_prev,
								nr_atendimento)
			values(					atend_paciente_prob_alta_seq.nextval,
								sysdate,
								:new.nm_usuario,
								sysdate,
								:new.nm_usuario,
								:new.ie_probabilidade_alta,
								:new.dt_previsto_alta,
								sysdate,
								:new.nr_atendimento);


		end if;

	end if;

	if	(:old.ie_tipo_atendimento <> :new.ie_tipo_atendimento) then

		select	decode(count(*),0,'N','S')
		into	ie_regra_gerar_pac_vacina_w
		from	regra_gerar_pac_vacina
		where	ie_tipo_atendimento = :new.ie_tipo_atendimento
		and	nvl(cd_estabelecimento, :new.cd_estabelecimento)	= :new.cd_estabelecimento
		and	nvl(ie_situacao,'A') = 'A';

		if	(ie_regra_gerar_pac_vacina_w = 'S') then
			inserir_pac_lista_espera_atend(:new.nr_atendimento, :new.cd_estabelecimento, :new.cd_pessoa_fisica, :new.nm_usuario);
		end if;

		/* Matheus OS 182242
		select 	nvl(max(nr_prontuario),0)
		into	nr_prontuario_w
		from	Pessoa_fisica
		where	cd_pessoa_fisica	= :new.cd_pessoa_fisica;*/

		nr_prontuario_w	:= nvl(obter_prontuario_pf(:new.cd_estabelecimento, :new.cd_pessoa_fisica),0);

		if 	(nr_prontuario_w = 0) then

			ie_gerar_w		:= 'N';
			obter_param_usuario(916, 533, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_gera_prontuario_w);

			if	(ie_gera_prontuario_w = 'S') and (:new.ie_tipo_atendimento = 1) then
				ie_gerar_w	:= 'S';
			elsif	(ie_prontuario_w = 'N') then
				ie_gerar_w	:= 'S';
			elsif	(ie_prontuario_w = 'R') then
				open c05;
				loop
				fetch c05 into ie_gerar_w;
				exit when c05%notfound;
				end loop;
				close c05;
			end if;
			if	(ie_gerar_w = 'S') then
				/* Matheus OS 182242
				select	prontuario_seq.nextval
				into	nr_prontuario_w
				from	dual;

				update 	pessoa_fisica
				set	nr_prontuario		= nr_prontuario_w
				where	cd_pessoa_fisica	= :new.cd_pessoa_fisica;*/
				gerar_prontuario_pac(:new.cd_estabelecimento, :new.cd_pessoa_fisica, 'N', :new.nm_usuario, nr_prontuario_w);
			end if;
		end if;

		fleury_limpa_validacao_atend( :new.nr_atendimento);

		ds_texto_w := 	substr(wheb_mensagem_pck.get_texto(301079) || ' ' || chr(13) || --Alteracao de tipo de atendimento:
				wheb_mensagem_pck.get_texto(301081) || ' ' || :new.cd_pessoa_fisica || chr(13) || --Pessoa:
				wheb_mensagem_pck.get_texto(301082) || ' ' || :new.nr_atendimento || chr(13) ||--Atend:
				'Obj: atendimento_paciente_UPDATE' || chr(13) ||
				'CALLSTACK: ' || dbms_utility.format_call_stack || chr(13) ||
				wheb_mensagem_pck.get_texto(301083) || ' ' || :old.ie_tipo_atendimento || chr(13) ||--Tipo atend. ant.
				wheb_mensagem_pck.get_texto(301084) || ' ' || :new.ie_tipo_atendimento,1,2000);--Tipo atend. novo.

		begin
		insert into log_atendimento(
			dt_atualizacao,
			nm_usuario,
			cd_log,
			nr_atendimento,
			ds_log)
		values	(sysdate,
			:new.nm_usuario,
			5,
			:new.nr_atendimento,
			ds_texto_w);
		exception
		when others then
			null;
		end;

		if	(:old.ie_tipo_atendimento is not null) then
			gerar_regra_prontuario_gestao(:new.ie_tipo_atendimento, :new.cd_estabelecimento, :new.nr_atendimento, :new.cd_pessoa_fisica, :new.nm_usuario, null, null, null, :new.ie_clinica, null, :new.ie_tipo_atendimento, null);
		end if;


		/*ds_param_integ_hl7_w :=	'cd_pessoa_fisica=' || :new.cd_pessoa_fisica || ds_sep_bv_w ||
							'nr_atendimento='   || :new.nr_atendimento   || ds_sep_bv_w ||
							'nr_seq_interno='   || null  || ds_sep_bv_w ||
							'nr_prescricao='    || null || ds_sep_bv_w ||
							'nr_seq_presc='	    || null  || ds_sep_bv_w ;

		gravar_agend_integracao(693, ds_param_integ_hl7_w);   */
	end if;

	cd_funcao_ativa_w := obter_funcao_ativa;
	if	((nvl(cd_funcao_ativa_w, 0) <> 0) and
		obter_se_perm_pf_classif(cd_funcao_ativa_w,0,:new.cd_pessoa_fisica,sysdate)	= 'N')  and
				(:new.dt_alta is null) and
		(:old.dt_alta is null) then
		wheb_mensagem_pck.exibir_mensagem_abort(186374);
		--'Esse paciente possui alguma classificacao nao permitida para essa funcao. #@#@'
	end if;
	begin
	if	(:new.nr_seq_triagem	<> :old.nr_seq_triagem) and
		(:new.nr_seq_triagem_old is null) and
		(obter_se_medico(obter_dados_usuario_opcao(wheb_usuario_pck.get_nm_usuario,'C'),'M')	= 'S') then
		:new.nr_seq_triagem_old	:= :old.nr_seq_triagem;
	end if;
	exception
	when others then
		null;
	end;
	begin
	if	(nvl(:new.nr_seq_triagem,0)	<> nvl(:old.nr_seq_triagem,0)) then
		begin
		insert into log_prioridade_atend(	nr_sequencia,
							dt_atualizacao,
							nm_usuario,
							dt_atualizacao_nrec,
							nm_usuario_nrec,
							nr_atendimento,
							nr_seq_triagem,
							nr_seq_triagem_old,
							ds_observacao,
							ds_stack)
			values			(	log_prioridade_atend_seq.nextval,
							sysdate,
							nvl(wheb_usuario_pck.get_nm_usuario, :new.nm_usuario),
							sysdate,
							nvl(wheb_usuario_pck.get_nm_usuario, :new.nm_usuario),
							:new.nr_atendimento,
							:new.nr_seq_triagem,
							:old.nr_seq_triagem,
							substr(wheb_assist_pck.get_obs_log_urgencia_atend,1,255),
							substr( wheb_mensagem_pck.get_texto(795196) || ': ' || obter_funcao_ativa || chr(10) || chr(13) ||
									wheb_mensagem_pck.get_texto(795195) || ': ' || obter_perfil_ativo || chr(10) || chr(13) ||
									dbms_utility.format_call_stack,1,2000)
							);

		wheb_assist_pck.set_obs_log_urgencia_atend(null);
		end;
	end if;

	exception
	when others then
		null;
	end;

	if	(nvl(:new.nr_seq_triagem,0)	<> nvl(:old.nr_seq_triagem,0)) then
		:new.dt_classif_risco := sysdate;
	end if;

	begin
	if	((:new.dt_alta is not null) and (:old.dt_alta is null)) or
		((:new.dt_alta_medico is not null) and (:old.dt_alta_medico is null)) or
		((:new.dt_previsto_alta is not null) and (:old.dt_previsto_alta is null)) or
		((:old.dt_alta is not null) and (:new.dt_alta is null)) or
		((:old.dt_alta_medico is not null) and (:new.dt_alta_medico is null)) or
		((:old.dt_previsto_alta is not null) and (:new.dt_previsto_alta is null)) or
		(:old.dt_alta <> :new.dt_alta) or
		(:old.dt_alta_medico <> :new.dt_alta_medico) or
		(:old.dt_previsto_alta <> :new.dt_previsto_alta) then
		eis_fechamento_part_alert_sign(:new.nm_usuario);
	end if;
	exception
	when others then
		null;
	end;

	if	(ie_altera_tipo_atend_protoc_w = 'N') and
		(nvl(:new.ie_tipo_atendimento, 0) <> nvl(:old.ie_tipo_atendimento, 0)) then

		select	count(*)
		into	qt_protocolo_atend_w
		from	protocolo_documento a,
			protocolo_doc_item b
		where	b.nr_sequencia = a.nr_sequencia
		and	b.nr_documento = :new.nr_atendimento
		and	a.ie_tipo_protocolo in (2, 5);

		if	(qt_protocolo_atend_w > 0) then
			wheb_mensagem_pck.exibir_mensagem_abort(195752);
		end if;

	end if;

	begin
	if	(((:old.dt_inicio_atendimento	is null  and
		:new.dt_inicio_atendimento is not null) or
		(:old.dt_atend_medico is null and
		:new.dt_atend_medico is not null))) and
		(:new.ie_chamado = 'X')then
		:new.ie_chamado	:= 'S';
	end if;
	exception
	when others then
		null;
	end;


	begin
	if	(:old.dt_fim_triagem is null and
		:new.dt_fim_triagem is not null) then
		:new.dt_chamada_paciente	:= null;
	end if;
	exception
	when others then
		null;
	end;


	select	nvl(max(ie_integracao_dynamics),'N')
	into	ie_integracao_dynamics_w
	from	parametro_atendimento
	where	cd_estabelecimento = :new.cd_estabelecimento;

	if	(:new.nr_submotivo_alta is not null) then
		select	max(nr_sequencia)
		into	nr_seq_alta_hist_w
		from	atend_alta_hist
		where	nr_atendimento = :new.nr_atendimento
		and		'A' = ie_alta_estorno;

		if (nvl(nr_seq_alta_hist_w,0) > 0) then

			update	atend_alta_hist
			set		nr_submotivo_alta = :new.nr_submotivo_alta
			where	nr_sequencia = nr_seq_alta_hist_w;
		end if;
	end if;

	-- Atualiza tabela de integracao CRM_ATENDIMENTOS
	if	(ie_integracao_dynamics_w = 'S') then
		select	count(*)
		into	qt_crm_atendimentos_w
		from	crm_atendimentos
		where	nr_atendimento = :new.nr_atendimento;

		if (qt_crm_atendimentos_w > 0) then
			if	(:old.ie_tipo_atendimento <> :new.ie_tipo_atendimento) then
				update	crm_atendimentos
				set	ie_tipo_atendimento 	= :new.ie_tipo_atendimento,
					ds_tipo_atendimento 	= substr(obter_nome_tipo_atend(:new.ie_tipo_atendimento),1,255),
					ie_status		= 2,
					dt_atualizacao		= sysdate,
					nm_usuario		= :new.nm_usuario
				where	nr_atendimento 		= :new.nr_atendimento;
			end if;
			if	(:old.dt_entrada <> :new.dt_entrada) then
				update	crm_atendimentos
				set	dt_entrada 	= to_char(:new.dt_entrada,'yyyy-mm-dd hh24:mi:ss'),
					ie_status	= 2,
					dt_atualizacao	= sysdate,
					nm_usuario	= :new.nm_usuario
				where	nr_atendimento	= :new.nr_atendimento;
			end if;
			if	(:old.cd_medico_resp <> :new.cd_medico_resp) then
				update	crm_atendimentos
				set	cd_medico_resp 	= :new.cd_medico_resp,
					nm_medico_resp 	= substr(obter_nome_medico(:new.cd_medico_resp,'N'),1,60),
					ie_status	= 2,
					dt_atualizacao	= sysdate,
					nm_usuario	= :new.nm_usuario
				where	nr_atendimento 	= :new.nr_atendimento;
			end if;
			if	((:old.cd_motivo_alta is not null) and (:new.cd_motivo_alta is null)) or
				((:old.dt_alta is not null) and (:new.dt_alta is null)) then
				update	crm_atendimentos
				set	dt_alta		= to_char(:new.dt_alta,'yyyy-mm-dd hh24:mi:ss'),
					ds_motivo_alta	= substr(obter_desc_motivo_alta(:new.cd_motivo_alta),1,60),
					cd_motivo_alta	= :new.cd_motivo_alta,
					ie_status	= 2,
					dt_atualizacao	= sysdate,
					nm_usuario	= :new.nm_usuario
				where	nr_atendimento 	= :new.nr_atendimento;
			end if;
			if	(:old.dt_alta is null) and (:new.dt_alta is not null) then
				update	crm_atendimentos
				set	dt_alta		= to_char(:new.dt_alta,'yyyy-mm-dd hh24:mi:ss'),
					ds_motivo_alta	= substr(obter_desc_motivo_alta(:new.cd_motivo_alta),1,60),
					cd_motivo_alta	= :new.cd_motivo_alta,
					dt_atualizacao	= sysdate,
					nm_usuario	= :new.nm_usuario
				where	nr_atendimento 	= :new.nr_atendimento;
			end if;
			if	((:old.dt_cancelamento is null) and (:new.dt_cancelamento is not null)) or
				((:old.dt_cancelamento is not null) and (:new.dt_cancelamento is null))	then
				update	crm_atendimentos
				set	ie_status	= decode(:new.dt_cancelamento,null,2,3),
					dt_atualizacao	= sysdate,
					nm_usuario	= :new.nm_usuario
				where	nr_atendimento 	= :new.nr_atendimento;
			end if;
		end if;
	end if;

	if	((:old.dt_cancelamento is null) and (:new.dt_cancelamento is not null)) then
		select 	nvl(max('S'),'N')
		into 	ie_trat_onc_w
		from	paciente_atendimento a 
		where 	a.nr_atendimento = :new.nr_atendimento;

		if (ie_trat_onc_w = 'S') then
			update  paciente_atendimento
			set 	nr_atendimento = null
			where 	nr_atendimento = :new.nr_atendimento;
		end if;
	end if;


	if	(nvl(:new.ie_paciente_isolado, 'N') <> nvl(:old.ie_paciente_isolado, 'N')) then

		ds_origem_w := substr(dbms_utility.format_call_stack,1,1800);
		ds_isolamento_log_w := substr(wheb_mensagem_pck.get_texto(301091)|| ' ' || chr(13) ||--Log de isolamento e liberacao de isolamento
						wheb_mensagem_pck.get_texto(301085,'DS_ORIGEM='|| ds_origem_w ||
									';NR_ATENDIMENTO='|| :new.nr_atendimento ||
									';NM_USUARIO='|| :new.nm_usuario ||
									';CD_FUNCAO='|| substr(obter_desc_funcao(obter_funcao_ativa),1,30)),1,2000);

		insert into log_atendimento(
			dt_atualizacao,
			nm_usuario,
			cd_log,
			nr_atendimento,
			ds_log)
			values	(sysdate,
				 :new.nm_usuario,
				 6,
				 :new.nr_atendimento,
				 ds_isolamento_log_w);
	end if;

	if	(nvl(:new.nr_seq_pac_senha_fila,0) <> nvl(:old.nr_seq_pac_senha_fila,0)) then

		obter_param_usuario(916, 1089, obter_perfil_ativo, :new.nm_usuario, :new.cd_estabelecimento, ie_vincular_senha_w);

		if	(ie_vincular_senha_w = 'C') then

			insert into senhas_atendimento (
				nr_sequencia,
				nr_seq_pac_senha_fila,
				nr_atendimento,
				dt_atualizacao,
				nm_usuario,
				dt_atualizacao_nrec,
				nm_usuario_nrec
			) values(	senhas_atendimento_seq.nextval,
				:new.nr_seq_pac_senha_fila,
				:new.nr_atendimento,
				sysdate,
				:new.nm_usuario,
				sysdate,
				:new.nm_usuario);
		end if;

	end if;

	if	(:new.ds_obs_alta is not null) and
		((nvl(:new.ds_obs_alta, 'N') <> nvl(:old.ds_obs_alta, 'N')) or
		 (nvl(:new.nr_seq_tipo_obs_alta, 0) <> nvl(:old.nr_seq_tipo_obs_alta, 0))) then

		insert into obs_alta_hist(
				nr_sequencia,
				dt_atualizacao,
				nm_usuario,
				nr_atendimento,
				ds_historico,
				dt_historico,
				dt_atualizacao_nrec,
				nm_usuario_nrec,
				nr_seq_tipo_obs_alta)
			values	(obs_alta_hist_seq.nextval,
				sysdate,
				:new.nm_usuario,
				:new.nr_atendimento,
				substr(:new.ds_obs_alta,1,2000),
				sysdate,
				sysdate,
				:new.nm_usuario,
				:new.nr_seq_tipo_obs_alta);

	end if;

	if 	(:old.ie_paciente_isolado = 'S') and
		(:new.ie_paciente_isolado = 'N') then

		select max(nr_seq_interno)
		into	nr_seq_unidade_w
		from	unidade_atendimento
		where	nr_atendimento = :new.nr_atendimento;
		gerar_higienizacao_leito_unid(sysdate, wheb_usuario_pck.get_nm_usuario, wheb_usuario_pck.get_cd_estabelecimento,'LPI', nr_seq_unidade_w, null);
	end if;

	/*
	if	(:new.dt_alta is not null) and
		(:old.dt_alta is null) then

		incluida na Procedure gerar_estornar_alta
		obter_param_usuario(281,1432,obter_perfil_ativo,:new.nm_usuario,:new.cd_estabelecimento,ie_finaliza_precaucao_w);

		if	(nvl(ie_finaliza_precaucao_w,'N') = 'S') then
			update	atendimento_precaucao
			set	dt_termino = sysdate,
				ds_just_fim_prec = 'Alta do paciente',
				nm_usuario_fim = :new.nm_usuario
			where	nr_atendimento = :new.nr_atendimento
			and	dt_termino is null;
		end if;
	end if;  */

	if 	('00/00/0000 00:00:00' = to_char(:new.dt_previsto_alta,'dd/mm/yyyy hh24:mi:ss')) then
		:new.dt_previsto_alta := null;
	end if;

	if ((:new.dt_alta_medico is not null) and (:old.dt_alta_medico is null)) then

		select	max(x.cd_setor_atendimento),
				max(x.cd_unidade_basica),
				max(x.cd_unidade_compl)
		into    cd_setor_atendimento_w,
				cd_unidade_basica_w,
				cd_unidade_compl_w
		from	(select	a.cd_setor_atendimento,
				 a.cd_unidade_basica,
				 a.cd_unidade_compl,
				 row_number() over (order by nvl(a.dt_saida_unidade, a.dt_entrada_unidade + 9999) desc) nr_controle_linha
				 from 	atend_paciente_unidade a, setor_atendimento c
				 where	a.nr_atendimento 		= :new.nr_atendimento
				 and	a.cd_setor_atendimento = c.cd_setor_atendimento
				 and	c.CD_CLASSIF_SETOR <> 2) x
		where	x.nr_controle_linha = 1;

		insert into integra_voice_hcs
			(NR_SEQUENCIA,
			DT_ATUALIZACAO,
			NM_USUARIO,
			DT_ATUALIZACAO_NREC,
			NM_USUARIO_NREC,
			NR_ATENDIMENTO,
			CD_SETOR_ATEND_ANT,
			CD_UNID_BASIC_ANT,
			CD_UNID_COMPL_ANT,
			CD_SETOR_ATENDIMENTO,
			CD_UNIDADE_BASICA,
			CD_UNIDADE_COMPL,
			IE_STATUS_UNIDADE,
			IE_EVENTO,
			DS_MENSAGEM,
			DT_ALTA_MEDICO)
		values
			(
			integra_voice_hcs_seq.nextval,
			sysdate,
			:new.nm_usuario,
			sysdate,
			:new.nm_usuario,
			:new.nr_atendimento,
			null,
			null,
			null,
			cd_setor_atendimento_w,
			cd_unidade_basica_w,
			cd_unidade_compl_w,
			null,
			'AM',
			null,
			:new.dt_alta_medico);

	end if;

	if ((:new.dt_alta_medico is null) and (:old.dt_alta_medico is not null) and obter_regra_voice_hcs('ES') = 'S') then


		select	max(x.cd_setor_atendimento),
				max(x.cd_unidade_basica),
				max(x.cd_unidade_compl)
		into    cd_setor_atendimento_w,
				cd_unidade_basica_w,
				cd_unidade_compl_w
		from	(select	a.cd_setor_atendimento,
				 a.cd_unidade_basica,
				 a.cd_unidade_compl,
				 row_number() over (order by nvl(a.dt_saida_unidade, a.dt_entrada_unidade + 9999) desc) nr_controle_linha
				 from 	atend_paciente_unidade a, setor_atendimento c
				 where	a.nr_atendimento 		= :new.nr_atendimento
				 and	a.cd_setor_atendimento = c.cd_setor_atendimento
				 and	c.CD_CLASSIF_SETOR <> 2) x
		where	x.nr_controle_linha = 1;

		begin
			select	nvl('S','N')
			into ie_existe_w
			from integra_voice_hcs
			where nr_atendimento = :new.nr_atendimento
			and cd_setor_atendimento = cd_setor_atendimento_w
			and cd_unidade_basica = cd_unidade_basica_w
			and cd_unidade_compl = cd_unidade_compl_w
			and DT_ATUALIZACAO = sysdate;	
			exception
			when others then
			ie_existe_w := 'N';
			end;			

		if (ie_existe_w = 'N') then

			insert into integra_voice_hcs
				(NR_SEQUENCIA,
				DT_ATUALIZACAO,
				NM_USUARIO,
				DT_ATUALIZACAO_NREC,
				NM_USUARIO_NREC,
				NR_ATENDIMENTO,
				CD_SETOR_ATEND_ANT,
				CD_UNID_BASIC_ANT,
				CD_UNID_COMPL_ANT,
				CD_SETOR_ATENDIMENTO,
				CD_UNIDADE_BASICA,
				CD_UNIDADE_COMPL,
				IE_STATUS_UNIDADE,
				IE_EVENTO,
				DS_MENSAGEM,
				DT_ALTA_MEDICO)
			values
				(
				integra_voice_hcs_seq.nextval,
				sysdate,
				:new.nm_usuario,
				sysdate,
				:new.nm_usuario,
				:new.nr_atendimento,
				null,
				null,
				null,
				cd_setor_atendimento_w,
				cd_unidade_basica_w,
				cd_unidade_compl_w,
				'ES',
				'RS',
				null,
				null);

		end if;
	end if;

	if	((:old.dt_alta <> :new.dt_alta) or
		 (:old.dt_alta is null and :new.dt_alta is not null) or
		 (:new.dt_alta is null and :old.dt_alta is not null)) then
		 consiste_tipo_visita_atend(nr_atendimento_p => :new.nr_atendimento,
						 nr_seq_tipo_admissao_fat_p => :new.nr_seq_tipo_admissao_fat,
						 cd_pessoa_fisica_p => :new.cd_pessoa_fisica,
						 nr_seq_episodio_p => :new.nr_seq_episodio,
						 dt_entrada_p => :new.dt_entrada,
						 dt_alta_p => :new.dt_alta,
						 ie_alteracao_p => 'D',
						 ie_alt_data_alta_p => 'S');

	elsif	((:old.dt_previsto_alta <> :new.dt_previsto_alta) or
		 (:old.dt_previsto_alta is null and :new.dt_previsto_alta is not null) or
		 (:new.dt_previsto_alta is null and :old.dt_previsto_alta is not null)) then
		 consiste_tipo_visita_atend(nr_atendimento_p => :new.nr_atendimento,
						 nr_seq_tipo_admissao_fat_p => :new.nr_seq_tipo_admissao_fat,
						 cd_pessoa_fisica_p => :new.cd_pessoa_fisica,
						 nr_seq_episodio_p => :new.nr_seq_episodio,
						 dt_entrada_p => :new.dt_entrada,
						 dt_previsto_alta_p => :new.dt_previsto_alta,
						 ie_alteracao_p => 'D',
						 ie_alt_data_prev_p	=> 'S');
	elsif	((:new.nr_seq_tipo_admissao_fat <> :old.nr_seq_tipo_admissao_fat) or
		 (:new.nr_seq_tipo_admissao_fat is not null and :old.nr_seq_tipo_admissao_fat is null) or
		 ((:new.dt_entrada <> :old.dt_entrada) and (:new.nr_seq_tipo_admissao_fat is not null))) then
		 consiste_tipo_visita_atend(nr_atendimento_p => :new.nr_atendimento, 
				   cd_pessoa_fisica_p => :new.cd_pessoa_fisica,
				   nr_seq_tipo_admissao_fat_p => :new.nr_seq_tipo_admissao_fat,
				   nr_seq_episodio_p => :new.nr_seq_episodio,
				   dt_entrada_p => :new.dt_entrada);

	end if;

	IF :new.dt_cancelamento IS NOT NULL THEN
		UPDATE pessoa_fisica_aux SET nr_primeiro_atend = NULL WHERE nr_primeiro_atend = :new.nr_atendimento;
	END IF;

	BEGIN
	  SELECT PFA.IE_MOTIVO_SEM_CPF,
			 PFA.IE_CONTROL_EXT
		INTO IE_MOTIVO_SEM_CPF_W,
			 IE_CONTROL_EXT_W
		FROM PESSOA_FISICA_AUX PFA
	   WHERE PFA.CD_PESSOA_FISICA = :NEW.CD_PESSOA_FISICA
		 AND ROWNUM <= 1;

	  BEGIN
		SELECT APA.*
		  INTO ATEND_PACIENTE_ADIC_W
		  FROM ATEND_PACIENTE_ADIC APA
		 WHERE APA.NR_ATENDIMENTO = :NEW.NR_ATENDIMENTO;
	  EXCEPTION
		WHEN NO_DATA_FOUND THEN
			 ATEND_PACIENTE_ADIC_W := NULL;
	  END;

	  ATEND_PACIENTE_ADIC_W.NR_ATENDIMENTO    := :NEW.NR_ATENDIMENTO;
	  ATEND_PACIENTE_ADIC_W.IE_MOTIVO_SEM_CPF := IE_MOTIVO_SEM_CPF_W;
	  ATEND_PACIENTE_ADIC_W.IE_CONTROLE_EXT   := IE_CONTROL_EXT_W;
	  ATEND_PACIENTE_ADIC_W.CD_PESSOA_FISICA  := :NEW.CD_PESSOA_FISICA;
	  ATEND_PACIENTE_ADIC_W.DT_ATUALIZACAO    := SYSDATE;
	  ATEND_PACIENTE_ADIC_W.NM_USUARIO        := :NEW.NM_USUARIO;

	  IF (ATEND_PACIENTE_ADIC_W.NM_USUARIO_NREC IS NULL) THEN
		 ATEND_PACIENTE_ADIC_W.NM_USUARIO_NREC := ATEND_PACIENTE_ADIC_W.NM_USUARIO;
	  END IF;

	  IF (ATEND_PACIENTE_ADIC_W.DT_ATUALIZACAO_NREC IS NULL) THEN
		 ATEND_PACIENTE_ADIC_W.DT_ATUALIZACAO_NREC := ATEND_PACIENTE_ADIC_W.DT_ATUALIZACAO;
	  END IF;

	  IF (ATEND_PACIENTE_ADIC_W.NR_SEQUENCIA IS NULL) THEN
		 SELECT ATEND_PACIENTE_ADIC_SEQ.NEXTVAL
		   INTO ATEND_PACIENTE_ADIC_W.NR_SEQUENCIA
		   FROM DUAL;

		 INSERT INTO ATEND_PACIENTE_ADIC
		 VALUES ATEND_PACIENTE_ADIC_W;
	  ELSE
		 UPDATE ATEND_PACIENTE_ADIC APA
			SET ROW = ATEND_PACIENTE_ADIC_W
		  WHERE APA.NR_SEQUENCIA = ATEND_PACIENTE_ADIC_W.NR_SEQUENCIA;
	  END IF;
	EXCEPTION
	  WHEN NO_DATA_FOUND THEN
		   NULL;
	END;

	if (:new.nr_seq_tipo_admissao_fat is not null and :new.ie_tipo_atendimento is null and nvl(pkg_i18n.get_user_locale, 'pt_BR') in ('de_DE', 'de_AT')) then
		:new.ie_tipo_atendimento := nvl(obter_tipo_atend_admissao(:new.nr_seq_tipo_admissao_fat), :new.ie_tipo_atendimento);
	end if;

	if (:old.ie_tipo_atendimento <> :new.ie_tipo_atendimento and nvl(pkg_i18n.get_user_locale, 'pt_BR') = 'ja_JP') then

	  GENERATE_CPOE_SLIP_NUMBER(:new.nr_atendimento,:new.ie_tipo_atendimento,:new.cd_pessoa_fisica,null,null,:new.nm_usuario);

	end if;

	if (NVL(pkg_i18n.get_user_locale, 'pt_BR') <> 'pt_BR') and (:new.ds_senha is not null) then
		:new.ds_senha := null;
	end if;

	/* BEGIN: WSUITE PATIENT PORTAL - ROUTINE FOR CREATING TASKS FOR THE PATIENT BASED ON SERVICE */
	if ((:new.cd_motivo_alta is not null) and
		((obter_se_motivo_alta_evasao(:new.cd_motivo_alta) <> 'S')
			or (obter_se_motivo_alta_obito(:new.cd_motivo_alta) <> 'S')
			or (obter_se_motivo_alta_trans(:new.cd_motivo_alta) <> 'S'))) then

			wsuite_agenda_regra_tarefa_pck.gerar_tarefa_pos_alta(
				:new.nr_atendimento,
				'EAP',
				:new.cd_estabelecimento,
				:new.nm_usuario,
				:new.cd_pessoa_fisica,
				:new.cd_medico_resp
			);
	end if;
	/* END: WSUITE PATIENT PORTAL - ROUTINE FOR CREATING TASKS FOR THE PATIENT BASED ON SERVICE */

	<<final>>

	null;

end;

ALTER TRIGGER "TASY"."ATENDIMENTO_PACIENTE_UPDATE" ENABLE
